/* ===================== BÀI 54 · Timing và tối ưu có đo ===================== */
/* Bài 54 · Timing và tối ưu có đo (AMTS-EMB-001-M14-L02, MC51-054) — sinh bởi tools/author/mcu8051/l54.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const P54=[{"label":"Ví dụ: Bấm giờ một đoạn code bằng Timer 0","code":"; Ví dụ 1: bấm giờ một đoạn code bằng Timer 0\n        ORG     0000H\n        MOV     TMOD,#01H               ; Timer 0 chế độ 1 (16 bit)\n        MOV     TH0,#00H\n        MOV     TL0,#00H\n        SETB    TR0                     ; đếm từ lệnh kế tiếp\n        MOV     R7,#10                  ; đoạn cần đo: 1 + 10 x 2\nLAP:    DJNZ    R7,LAP\n        CLR     TR0                     ; lệnh dừng cũng được đếm\n        MOV     30H,TL0                 ; số đếm = 21 + 1\n        MOV     31H,TH0\n        SJMP    $\n        END\n","note":"Đoán trước: TL0 cuối bằng bao nhiêu? Đoạn đo gồm MOV R7,#10 (1 chu kỳ) và 10 lần DJNZ (20 chu kỳ) = 21; SETB TR0 không được đếm, CLR TR0 được đếm nên TL0 = 22 = 16H. Đo đoạn rỗng (SETB TR0 rồi CLR TR0 liền nhau) sẽ được 1: đó là phí đo cần trừ.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Hai cách đếm bit 1, đo rồi mới chọn","code":"; Ví dụ 2: hai cách đếm bit 1 của R2 - đo rồi mới chọn\n        ORG     0000H\n        MOV     TMOD,#01H\n        MOV     R2,#0B7H                ; 1011 0111: có 6 bit 1\n; ---- cách A: dịch 8 lần qua cờ CY\n        MOV     TL0,#00H\n        SETB    TR0\n        MOV     A,R2\n        MOV     R3,#8\n        MOV     R4,#00H\nLA:     RLC     A\n        JNC     KA\n        INC     R4\nKA:     DJNZ    R3,LA\n        CLR     TR0\n        MOV     30H,R4                  ; kết quả cách A\n        MOV     31H,TL0                 ; chu kỳ cách A (+1 phí đo)\n; ---- cách B: tra bảng 16 nửa byte (nibble)\n        MOV     TL0,#00H\n        SETB    TR0\n        MOV     DPTR,#BANG\n        MOV     A,R2\n        ANL     A,#0FH                  ; nửa thấp\n        MOVC    A,@A+DPTR\n        MOV     R4,A\n        MOV     A,R2\n        SWAP    A                       ; nửa cao\n        ANL     A,#0FH\n        MOVC    A,@A+DPTR\n        ADD     A,R4\n        CLR     TR0\n        MOV     32H,A                   ; kết quả cách B\n        MOV     33H,TL0                 ; chu kỳ cách B (+1 phí đo)\n        SJMP    $\nBANG:   DB      0,1,1,2,1,2,2,3,1,2,2,3,2,3,3,4\n        END\n","note":"Cùng dữ liệu B7H, hai cách cùng ra 6 bit 1 (30H = 32H = 06H). Số đếm: cách A 50 (31H = 32H), cách B 14 (33H = 0EH); trừ phí đo: 49 và 13 chu kỳ. Cách B nhanh gần 4 lần nhưng tốn thêm 16 byte bảng. Đổi R2 thành 00H hoặc FFH rồi chạy lại: cách A đổi số chu kỳ theo dữ liệu, cách B không.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Độ trễ ngắt phụ thuộc lệnh đang chạy","code":"; Ví dụ 3: độ trễ ngắt phụ thuộc lệnh đang chạy\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH                   ; vectơ Timer 0\n        MOV     @R0,TL0                 ; số chu kỳ từ lúc tràn tới đây\n        INC     R0\n        CLR     TR0\n        RETI\n        ORG     0030H\nMAIN:   MOV     R0,#30H\n        MOV     TMOD,#02H               ; chế độ 2: sau tràn TL0 = TH0\n        MOV     TH0,#00H\n        MOV     IE,#82H                 ; EA, ET0\n        MOV     TL0,#0FEH               ; lần 1: tràn khi CPU chạy NOP\n        SETB    TR0\n        NOP\n        NOP\n        NOP\n        NOP\n        NOP\n        MOV     TL0,#0FFH               ; lần 2: tràn ở NOP, ngay sau\n        SETB    TR0                     ; là MUL AB (4 chu kỳ)\n        NOP\n        MUL     AB\n        NOP\n        CLR     EA\n        SJMP    $\n        END\n","note":"Lần 1: TL0 tràn ở NOP thứ hai (chu kỳ cuối của lệnh) nên CPU chạy thêm NOP kế tiếp, rồi LCALL 2 chu kỳ; lệnh MOV @R0,TL0 đọc TL0 = 4 (30H). Lần 2: tràn ở NOP, lệnh kế tiếp là MUL AB 4 chu kỳ, nên đọc được 7 (31H). Jitter 3 chu kỳ chỉ vì lệnh đang chạy khác nhau.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Tải CPU của tác vụ mỗi tick 1 ms","code":"; Ví dụ 4: tải CPU của một tác vụ chạy mỗi tick 1 ms\n        ORG     0000H\n        MOV     TMOD,#01H\n        MOV     TH0,#00H\n        MOV     TL0,#00H\n        SETB    TR0\n        ACALL   TACVU                   ; đo cả ACALL và RET\n        CLR     TR0\n        MOV     A,TL0\n        DEC     A                       ; trừ 1 chu kỳ phí đo\n        MOV     30H,A                   ; T = số chu kỳ của tác vụ\n        MOV     B,#10                   ; tick 1 ms = 1000 chu kỳ (12 MHz)\n        DIV     AB                      ; T / 10 = tải tính theo %\n        MOV     31H,A                   ; phần nguyên (%)\n        MOV     32H,B                   ; phần mười của %\n        SJMP    $\nTACVU:  MOV     R7,#20                  ; giả định: cộng dồn 20 mẫu\nL1:     MOV     A,R7\n        ADD     A,40H\n        MOV     40H,A\n        DJNZ    R7,L1\n        RET\n        END\n","note":"TACVU (kể cả ACALL, RET) tốn 2 + 1 + 20 × 5 + 2 = 105 chu kỳ: 30H = 69H. Tick 1 ms ở 12 MHz là 1 000 chu kỳ, nên tải = 105 / 10 = 10 dư 5 → 31H = 0AH, 32H = 05H, tức 10,5 %. Ô 40H = 20 + 19 + … + 1 = 210 = D2H.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Bỏ MUL AB vì nghĩ nó chậm","code":"; Bẫy: thay MUL AB bằng vòng dịch-cộng \"cho nhanh\"\n        ORG     0000H\n        MOV     TMOD,#01H\n        MOV     TL0,#00H\n        MOV     R2,#37                  ; tính 37 x 10\n        SETB    TR0\n        MOV     A,R2                    ; cách 1: MUL AB\n        MOV     B,#10\n        MUL     AB                      ; 370 = 0172H: B = 01H, A = 72H\n        CLR     TR0\n        MOV     30H,A\n        MOV     31H,TL0                 ; chu kỳ cách 1 (+1 phí đo)\n        MOV     TL0,#00H\n        SETB    TR0\n        MOV     R3,#10                  ; cách 2: số nhân, xét từ bit cao\n        MOV     R4,#00H                 ; tích (chỉ giữ 8 bit thấp)\n        MOV     R5,#8\nLAP:    MOV     A,R4\n        ADD     A,R4                    ; tích = tích x 2\n        MOV     R4,A\n        MOV     A,R3\n        RLC     A                       ; bit cao của số nhân vào CY\n        MOV     R3,A\n        JNC     BO\n        MOV     A,R4\n        ADD     A,R2                    ; bit = 1: cộng số bị nhân\n        MOV     R4,A\nBO:     DJNZ    R5,LAP\n        CLR     TR0\n        MOV     32H,R4\n        MOV     33H,TL0                 ; chu kỳ cách 2 (+1 phí đo)\n        SJMP    $\n        END\n","note":"Cách 1 (MUL AB) đếm 8 = 7 chu kỳ + 1 phí đo; cách 2 (vòng dịch-cộng 8 lần) đếm 90 = 89 + 1, cả hai cho 72H (370 = 0172H; cách 2 chỉ giữ 8 bit thấp, mất luôn byte cao 01H mà MUL đặt vào B). “Tối ưu” theo cảm giác vừa chậm hơn 12 lần vừa sai yêu cầu 16 bit.","dev":{"led":true},"fosc":12000000}];
const sim54=makeSim51(document.getElementById("m51-l54"),{id:"s54",presets:P54,ram:256});
makeEx51(document.getElementById("ex-l54"),"l54",[{"t":"Bấm giờ một vòng trễ bằng Timer 0","d":"<p>Ô <code>40H<\/code> chứa số <i>N<\/i>. Đoạn code cần đo gồm hai dòng <code>MOV R7,40H<\/code> và <code>LAP: DJNZ R7,LAP<\/code>. Viết chương trình đo đoạn đó bằng Timer 0 ở chế độ 16 bit: đặt <code>SETB TR0<\/code> ngay trước đoạn và <code>CLR TR0<\/code> ngay sau đoạn; ghi số đếm thô <code>TL0<\/code> vào <code>30H<\/code>, <code>TH0<\/code> vào <code>31H<\/code>; rồi trừ phí đo 1 chu kỳ, ghi số chu kỳ thật của đoạn (16 bit) vào <code>32H<\/code> (byte thấp) và <code>33H<\/code> (byte cao). TH0, TL0 bằng 0 sau reset. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>40H = 10<\/code> → số đếm = 2 + 10 × 2 + 1 = 23 → <code>30H = 17H<\/code>, <code>31H = 00H<\/code>, <code>32H = 16H<\/code>, <code>33H = 00H<\/code>.<\/p>","start":"        ORG     0000H\n        SETB    TR0                     ; Timer 0 đang ở chế độ nào?\n        MOV     R7,40H                  ; đoạn cần đo\nLAP:    DJNZ    R7,LAP\n        CLR     TR0\n        MOV     30H,TL0\n        MOV     31H,TH0\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x40":10,"0x30":238,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":23,"0x31":0,"0x32":22,"0x33":0,"0x40":10}}},{"setup":{"iram":{"0x40":200,"0x30":238,"0x31":238,"0x32":238,"0x33":238},"regs":{"PSW":128}},"expect":{"iram":{"0x30":147,"0x31":1,"0x32":146,"0x33":1,"0x40":200}}},{"setup":{"iram":{"0x40":0,"0x30":238,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":3,"0x31":2,"0x32":2,"0x33":2,"0x40":0}}},{"setup":{"iram":{"0x40":1,"0x30":238,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":5,"0x31":0,"0x32":4,"0x33":0,"0x40":1}}},{"setup":{"iram":{"0x40":127,"0x30":238,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":1,"0x31":1,"0x32":0,"0x33":1,"0x40":127}}},{"setup":{"iram":{"0x40":255,"0x30":238,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":1,"0x31":2,"0x32":0,"0x33":2,"0x40":255}}}]},"hints":["Code mẫu đạt bộ thử 1 nhưng trượt khi N lớn. Sau reset TMOD = 00H: Timer 0 đang ở chế độ nào, TL0 đếm được bao nhiêu bit?","Chế độ 1 (16 bit): MOV TMOD,#01H trước khi bật TR0. Lệnh ghi TMOD không nằm trong đoạn đo nên không làm sai số đếm.","Số đếm gồm cả chu kỳ của lệnh dừng timer: trừ 16 bit phần phí đo đó. Kiểm trường hợp byte thấp bằng 00H."],"why":"Sau reset TMOD = 00H nên Timer 0 ở chế độ 0 (13 bit): TL0 chỉ đếm 5 bit rồi nhảy sang TH0. Số đếm nhỏ hơn 32 trông vẫn đúng, số lớn thì sai. Đo phải chọn đúng chế độ 16 bit, đọc đủ TH0:TL0 và trừ phí đo +1 bằng phép trừ 16 bit (bộ thử 5: 0101H − 1 = 0100H, mượn sang byte cao; bộ thử 3: N = 0 làm DJNZ chạy 256 lần)."},{"t":"Thống kê độ trễ: min, max, jitter","d":"<p>Tám lần đo độ trễ ngắt (đơn vị chu kỳ máy, số không dấu) nằm ở <code>40H<\/code>–<code>47H<\/code>. Ghi giá trị nhỏ nhất vào <code>30H<\/code>, lớn nhất vào <code>31H<\/code> và jitter = lớn nhất − nhỏ nhất vào <code>32H<\/code>. Các ô <code>40H<\/code>–<code>47H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>05 07 04 09 05 06 07 05<\/code> → <code>30H = 04H<\/code>, <code>31H = 09H<\/code>, <code>32H = 05H<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     30H,#00H                ; min\n        MOV     31H,#00H                ; max\n        MOV     R0,#40H\nLAP:    MOV     A,@R0\n        CJNE    A,30H,$+3               ; CY = 1 nếu A < min\n        JNC     KMIN\n        MOV     30H,A\nKMIN:   CJNE    A,31H,$+3               ; CY = 1 nếu A < max\n        JC      KMAX\n        MOV     31H,A\nKMAX:   INC     R0\n        CJNE    R0,#48H,LAP\n        MOV     A,31H\n        CLR     C\n        SUBB    A,30H                   ; jitter = max - min\n        MOV     32H,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x40":5,"0x41":7,"0x42":4,"0x43":9,"0x44":5,"0x45":6,"0x46":7,"0x47":5,"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":4,"0x31":9,"0x32":5,"0x40":5,"0x41":7,"0x42":4,"0x43":9,"0x44":5,"0x45":6,"0x46":7,"0x47":5}}},{"setup":{"iram":{"0x40":12,"0x41":15,"0x42":13,"0x43":11,"0x44":14,"0x45":12,"0x46":16,"0x47":13,"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":11,"0x31":16,"0x32":5,"0x40":12,"0x41":15,"0x42":13,"0x43":11,"0x44":14,"0x45":12,"0x46":16,"0x47":13}}},{"setup":{"iram":{"0x40":0,"0x41":255,"0x42":128,"0x43":127,"0x44":1,"0x45":254,"0x46":64,"0x47":32,"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":255,"0x32":255,"0x40":0,"0x41":255,"0x42":128,"0x43":127,"0x44":1,"0x45":254,"0x46":64,"0x47":32}}},{"setup":{"iram":{"0x40":30,"0x41":20,"0x42":10,"0x43":9,"0x44":8,"0x45":7,"0x46":6,"0x47":3,"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":3,"0x31":30,"0x32":27,"0x40":30,"0x41":20,"0x42":10,"0x43":9,"0x44":8,"0x45":7,"0x46":6,"0x47":3}}},{"setup":{"iram":{"0x40":6,"0x41":6,"0x42":6,"0x43":6,"0x44":6,"0x45":6,"0x46":6,"0x47":6,"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":6,"0x31":6,"0x32":0,"0x40":6,"0x41":6,"0x42":6,"0x43":6,"0x44":6,"0x45":6,"0x46":6,"0x47":6}}},{"setup":{"iram":{"0x40":129,"0x41":144,"0x42":160,"0x43":133,"0x44":136,"0x45":159,"0x46":192,"0x47":130,"0x30":238,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":129,"0x31":192,"0x32":63,"0x40":129,"0x41":144,"0x42":160,"0x43":133,"0x44":136,"0x45":159,"0x46":192,"0x47":130}}}]},"hints":["Chạy code mẫu với bộ thử 1: vì sao min luôn ra 00H?","Giá trị khởi đầu của min phải lớn hơn hoặc bằng mọi mẫu (0FFH), hoặc lấy chính mẫu đầu tiên làm min và max.","CJNE A,30H,$+3 không nhảy đi đâu cả nhưng đặt CY = 1 khi A &lt; [30H]: đó là cách so sánh không dấu thường dùng trên 8051."],"why":"Min khởi đầu bằng 00H thì không mẫu nào nhỏ hơn được, nên min sai và jitter sai. Bộ thử 5 (mọi mẫu bằng nhau, jitter 0) và bộ thử 3 (có mẫu 00H và FFH) kiểm biên của phép so sánh không dấu."},{"t":"Đếm bit 1 của 8 byte, ≤ 150 chu kỳ","d":"<p>Tám byte ở <code>40H<\/code>–<code>47H<\/code>. Ghi tổng số bit 1 của cả 8 byte (0…64) vào <code>30H<\/code>; các ô <code>40H<\/code>–<code>47H<\/code> giữ nguyên. Code mẫu dịch từng bit qua cờ CY: đúng nhưng mất hơn 360 chu kỳ máy. Viết lại để chạy không quá <b>150 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) với mọi bộ thử, mã (kể cả bảng <code>DB<\/code>) không quá <b>48 byte<\/b>. Đo trên trình mô phỏng trước và sau khi sửa.<\/p><p>Ví dụ: <code>40H..47H = 01 03 07 0F 1F 3F 7F FF<\/code> → <code>30H = 24H<\/code> (36).<\/p>","start":"        ORG     0000H\n        MOV     R0,#40H\n        MOV     R2,#00H                 ; tổng số bit 1\nLAP:    MOV     A,@R0\n        MOV     R3,#8\nVONG:   RLC     A                       ; bit cao nhất vào CY\n        JNC     KHONG\n        INC     R2\nKHONG:  DJNZ    R3,VONG\n        INC     R0\n        CJNE    R0,#48H,LAP\n        MOV     30H,R2\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x40":1,"0x41":3,"0x42":7,"0x43":15,"0x44":31,"0x45":63,"0x46":127,"0x47":255,"0x30":238}},"expect":{"iram":{"0x30":36,"0x40":1,"0x41":3,"0x42":7,"0x43":15,"0x44":31,"0x45":63,"0x46":127,"0x47":255}}},{"setup":{"iram":{"0x40":0,"0x41":0,"0x42":0,"0x43":0,"0x44":0,"0x45":0,"0x46":0,"0x47":0,"0x30":238}},"expect":{"iram":{"0x30":0,"0x40":0,"0x41":0,"0x42":0,"0x43":0,"0x44":0,"0x45":0,"0x46":0,"0x47":0}}},{"setup":{"iram":{"0x40":255,"0x41":255,"0x42":255,"0x43":255,"0x44":255,"0x45":255,"0x46":255,"0x47":255,"0x30":238}},"expect":{"iram":{"0x30":64,"0x40":255,"0x41":255,"0x42":255,"0x43":255,"0x44":255,"0x45":255,"0x46":255,"0x47":255}}},{"setup":{"iram":{"0x40":128,"0x41":64,"0x42":32,"0x43":16,"0x44":8,"0x45":4,"0x46":2,"0x47":1,"0x30":238}},"expect":{"iram":{"0x30":8,"0x40":128,"0x41":64,"0x42":32,"0x43":16,"0x44":8,"0x45":4,"0x46":2,"0x47":1}}},{"setup":{"iram":{"0x40":240,"0x41":15,"0x42":240,"0x43":15,"0x44":170,"0x45":85,"0x46":165,"0x47":90,"0x30":238}},"expect":{"iram":{"0x30":32,"0x40":240,"0x41":15,"0x42":240,"0x43":15,"0x44":170,"0x45":85,"0x46":165,"0x47":90}}},{"setup":{"iram":{"0x40":18,"0x41":52,"0x42":86,"0x43":120,"0x44":154,"0x45":188,"0x46":222,"0x47":241,"0x30":238}},"expect":{"iram":{"0x30":33,"0x40":18,"0x41":52,"0x42":86,"0x43":120,"0x44":154,"0x45":188,"0x46":222,"0x47":241}}}],"maxCyc":150,"maxBytes":48},"hints":["Code mẫu tốn khoảng 45 chu kỳ cho mỗi byte: 8 lần RLC, JNC, DJNZ. Phải giảm xuống dưới 18 chu kỳ mỗi byte.","Bảng 16 phần tử (số bit 1 của 0…15) chỉ tốn 16 byte. Mỗi byte tra hai lần: nửa thấp (ANL A,#0FH) và nửa cao (SWAP A rồi ANL).","Nạp con trỏ bảng một lần ngoài vòng lặp; cộng dồn trong một thanh ghi."],"why":"Đổi bộ nhớ lấy thời gian: bảng 16 byte cho mỗi byte dữ liệu còn khoảng 17 chu kỳ (2 lần MOVC 2 chu kỳ, ANL, SWAP, ADD…) thay vì khoảng 45. Bảng 256 byte nhanh hơn nữa nhưng vượt chỉ tiêu 48 byte — tối ưu luôn có ràng buộc, và chỉ chọn được khi đo cả hai phía."}]);

makeQuiz("quiz54","score54",[{"q": "Timer 0 chế độ 1, TH0 = TL0 = 0. Chạy SETB TR0, rồi đoạn code 10 chu kỳ máy, rồi CLR TR0 (quy ước đếm của trình mô phỏng). TL0 bằng bao nhiêu?", "o": ["11", "10", "12", "9"], "a": 0, "e": "Chu kỳ của SETB TR0 không được đếm (TR0 bật ở cuối lệnh), chu kỳ của CLR TR0 được đếm (TR0 tắt ở cuối lệnh): 10 + 1 = 11. Đo đoạn rỗng để biết phí đo rồi trừ."}, {"q": "Cờ TF0 bật đúng chu kỳ cuối của lệnh NOP; lệnh kế tiếp là MUL AB. Theo mô tả của Intel, CPU vào ngắt khi nào?", "o": ["Ngay sau NOP, trước khi MUL AB bắt đầu", "Sau khi MUL AB chạy xong, rồi mới LCALL tới vectơ", "Giữa MUL AB, sau chu kỳ máy thứ hai của nó", "Sau MUL AB và thêm một lệnh nữa mới LCALL"], "a": 1, "e": "Cờ bật ở chu kỳ cuối của lệnh chỉ được hỏi vòng ở chu kỳ cuối của lệnh kế tiếp, nên MUL AB (4 chu kỳ) phải chạy hết, rồi phần cứng mới chèn LCALL. Đây là nguồn jitter của ví dụ 3."}, {"q": "Ở 12 MHz, một tác vụ chạy mỗi 1 ms và tốn 150 chu kỳ máy (đo cả ACALL/RET). Tải CPU của tác vụ là bao nhiêu?", "o": ["1,5 %", "150 %", "15 %", "12,5 %"], "a": 2, "e": "1 ms ở 12 MHz là 1 000 chu kỳ máy; 150 / 1 000 = 15 %. Đáp án 1,5 % nhầm 1 ms thành 10 000 chu kỳ."}, {"q": "Đo độ trễ ngắt 6 lần được 4, 7, 5, 4, 6, 7 chu kỳ. Jitter là bao nhiêu?", "o": ["7 chu kỳ", "5,5 chu kỳ", "3 chu kỳ", "4 chu kỳ"], "a": 2, "e": "Jitter = lớn nhất − nhỏ nhất = 7 − 4 = 3 chu kỳ. 5,5 là trung bình, 7 là độ trễ xấu nhất — hai số đó cũng cần báo cáo nhưng không phải jitter."}, {"q": "Hàm đếm bit 1 cần chạy ≤ 150 chu kỳ cho 8 byte và mã ≤ 48 byte. Lựa chọn nào hợp lý?", "o": ["Bảng 256 byte vì tra một lần là nhanh nhất", "Giữ vòng dịch 8 lần vì mã ngắn nhất", "Viết lại bằng MUL AB cho từng byte", "Bảng 16 nửa byte, rồi đo lại cả chu kỳ và byte"], "a": 3, "e": "Bảng 256 byte nhanh hơn nhưng vượt chỉ tiêu byte; vòng dịch không đạt chỉ tiêu chu kỳ. Bảng 16 nửa byte đạt cả hai — phải đo để khẳng định (bài tập 3)."}]);

